import sys

lines = [ln.strip() for ln in sys.stdin.read().splitlines() if ln.strip()]

thoughts = actions = observations = 0
step = 0
for i, line in enumerate(lines):
    if line.startswith('Thought:'):
        thoughts += 1
    elif line.startswith('Observation:'):
        observations += 1
    elif line.startswith('Action:'):
        actions += 1
        step += 1
        body = line[len('Action:'):].strip()
        if '[' in body and body.endswith(']'):
            tool = body[:body.index('[')].strip()
            arg = body[body.index('[') + 1:-1].strip()
        else:
            tool, arg = body, ''
        if i + 1 < len(lines) and lines[i + 1].startswith('Observation:'):
            obs = lines[i + 1][len('Observation:'):].strip()
        else:
            obs = '(none)'
        print(f'step {step}: {tool}({arg}) -> {obs}')
print(f'Thoughts: {thoughts}')
print(f'Actions: {actions}')
print(f'Observations: {observations}')
